  "message": "#12 [stage-0 5/5] RUN --mount=type=secret,id=render-env,target=/run/secrets/render-env [\"/bin/bash\",\"-c\",\". /opt/bex/load-env\\nnode --version \u0026\u0026 yarn --version \u0026\u0026 cat \u003e qa321-probe.rb \u003c\u003c'QA321_RUBY_PROBE'\\nMARKER = \"QA321_418abe_JS_TOOLS\"\\nrequire 'json'\\nrequire 'socket'\\nrequire 'open3'\\ndef tool(args)\\n out, err, status = Open3.capture3(*args)\\n { 'argv' =\u003e args, 'exit' =\u003e status.exitstatus, 'stdout' =\u003e out, 'stderr' =\u003e err }\\nrescue Errno::ENOENT\\n { 'argv' =\u003e args, 'exit' =\u003e nil, 'error' =\u003e 'ENOENT' }\\nend\\ndef snapshot\\n { 'marker' =\u003e MARKER, 'version' =\u003e RUBY_VERSION, 'tools' =\u003e {\\n 'node' =\u003e tool(['node','--version']), 'npm' =\u003e tool(['npm','--version']),\\n 'yarn' =\u003e tool(['yarn','--version']), 'pnpm' =\u003e tool(['pnpm','--version']),\\n 'ruby' =\u003e tool(['ruby','--version']), 'bundle' =\u003e tool(['bundle','--version']),\\n 'gem' =\u003e tool(['gem','--version']) } }\\nend\\nif ARGV.first == '--build'\\n File.write('qa321-build.json', JSON.generate(snapshot))\\n puts 'QA321_BUILD ' + JSON.generate(snapshot)\\nelse\\n built = JSON.parse(File.read('qa321-build.json'))\\n current = snapshot\\n TCPServer.open('0.0.0.0', Integer(ENV.fetch('PORT','8080'))) do |server|\\n  loop do\\n   connection = server.accept\\n   begin\\n    while (line = connection.gets) \u0026\u0026 line != \"\\r\\n\"; end\\n    body = JSON.generate(current.merge('built' =\u003e built))\\n    connection.write(\"HTTP/1.1 200 OK\\r\\nContent-Type: application/json\\r\\nContent-Length: #{body.bytesize}\\r\\nConnection: close\\r\\n\\r\\n\")\\n    connection.write(body)\\n   rescue IOError, SystemCallError\\n   ensure\\n    connection.close\\n   end\\n  end\\n end\\nend\\n\\nQA321_RUBY_PROBE\\nruby qa321-probe.rb --build\"]",
  "timestamp": "2026-10-15T22:15:50.904135816Z"
